function compatible(donor, recipient){ donor=String(donor||'').toUpperCase(); recipient=String(recipient||'').toUpperCase();
  var m=/^([ABO]+)([+-])$/.exec(donor), n=/^([ABO]+)([+-])$/.exec(recipient);
  if(!m||!n) return {error:'血型格式须如 O+、A-、AB+'};
  var dA=m[1], dR=m[2], rA=n[1], rR=n[2];
  var dHasA=dA.indexOf('A')>=0, dHasB=dA.indexOf('B')>=0, rHasA=rA.indexOf('A')>=0, rHasB=rA.indexOf('B')>=0;
  var aboOk=(!dHasA||rHasA)&&(!dHasB||rHasB);
  var rhOk=(dR==='-')||(dR===rR);
  var ok=aboOk&&rhOk;
  return {compatible:ok, note: ok?'可输血':'不可输血', donor:donor, recipient:recipient}; }
var EXPORTS={compatible:compatible};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BloodTypeForgePure = EXPORTS; }
